const input = $input.first().json;
const lista = input.data?.payload || input.payload || [];

const CANAL_POR_TIPO = {
  'Channel::Whatsapp': 'whatsapp',
  'Channel::FacebookPage': 'facebook',
  'Channel::Instagram': 'instagram',
  'Channel::WebWidget': 'website',
  'Channel::Telegram': 'telegram',
  'Channel::Sms': 'sms'
};

const conversas = lista.map(c => {
  const ultimaMsg = (c.messages || [])[c.messages.length - 1];
  return {
    id: c.id,
    nome: c.meta?.sender?.name || 'Sem nome',
    canal: CANAL_POR_TIPO[c.meta?.channel] || CANAL_POR_TIPO[c.inbox?.channel_type] || 'outro',
    ultima_mensagem: ultimaMsg?.content || '',
    nao_lida: (c.unread_count || 0) > 0,
    status: c.status,
    atualizado_em: c.timestamp || c.last_activity_at || null
  };
});

// Mais recente primeiro — o Chatwoot já costuma devolver assim, mas não
// custa garantir em vez de confiar na ordem que veio.
conversas.sort((a, b) => (b.atualizado_em || 0) - (a.atualizado_em || 0));

return [{ json: { conversas } }];
